namespace Ordering;

/// <summary>Handles product returns, the refunds they trigger and restocking.</summary>
public sealed class ReturnsHandler
{
    private readonly ReturnOperations _operations = new();

    public string ProcessReturn(Order order, Customer customer) =>
        _operations.ProcessReturn(order, customer);

    public bool IsReturnable(Order order) =>
        _operations.IsReturnable(order);

    public decimal ComputeRefund(Order order) =>
        _operations.ComputeRefund(order);

    public void LogRefund(Order order, decimal amount) =>
        _operations.LogRefund(order, amount);

    public int Restock(Order order) =>
        _operations.Restock(order);
}

internal sealed class ReturnOperations
{
    private readonly ReturnState _state = new();
    private readonly RefundService _refunds = new();

    public string ProcessReturn(Order order, Customer customer) =>
        ReturnAcceptance.Process(order, customer, _state);

    public bool IsReturnable(Order order) =>
        ReturnEligibility.IsReturnable(order, _state);

    public decimal ComputeRefund(Order order) =>
        _refunds.Compute(order);

    public void LogRefund(Order order, decimal amount) =>
        _refunds.Log(order, amount);

    public int Restock(Order order) =>
        RestockService.Restock(order, _state);
}

internal sealed class ReturnState
{
    public HashSet<string> ProcessedReferences { get; } = new(StringComparer.Ordinal);

    public Dictionary<string, int> RestockBySku { get; } = new(StringComparer.Ordinal);
}

internal static class ReturnAcceptance
{
    public static string Process(Order order, Customer customer, ReturnState state)
    {
        if (string.IsNullOrEmpty(order.Reference))
            return "missing reference";
        if (state.ProcessedReferences.Contains(order.Reference))
            return "already processed";
        if (order.Lines.Count == 0)
            return "nothing to return";
        if (customer.Tier == CustomerTier.Blocked)
            return "customer blocked";

        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 100)
                return "quantity too high";

            state.RestockBySku[line.Sku] = state.RestockBySku.TryGetValue(line.Sku, out var count)
                ? count + line.Quantity
                : line.Quantity;
        }

        if (state.RestockBySku.Count == 0)
            return "no returnable lines";

        state.ProcessedReferences.Add(order.Reference);
        return "accepted";
    }
}

internal static class ReturnEligibility
{
    public static bool IsReturnable(Order order, ReturnState state)
    {
        if (string.IsNullOrEmpty(order.Reference) || order.Lines.Count == 0)
            return false;
        if (state.ProcessedReferences.Contains(order.Reference))
            return false;

        var valid = 0;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (string.IsNullOrEmpty(line.Sku))
                continue;
            if (line.Quantity > 100)
                continue;
            if (line.Quantity >= 1 && line.Quantity <= 100)
                valid++;
        }

        return valid > 0;
    }
}

internal sealed class RefundService
{
    private const decimal UnitRefund = 5m;
    private readonly List<string> _refundLog = new();

    public decimal Compute(Order order)
    {
        decimal refund = 0m;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 50)
                refund += line.Quantity * UnitRefund * 0.9m;
            else if (line.Quantity > 10)
                refund += line.Quantity * UnitRefund * 0.95m;
            else if (line.Quantity > 1)
                refund += line.Quantity * UnitRefund;
            else
                refund += UnitRefund;
        }

        if (_refundLog.Count > 1000 && refund > 0m)
            refund = Math.Min(refund, 10000m);
        if (refund > 5000m)
            refund *= 0.99m;

        return refund < 0m ? 0m : refund;
    }

    public void Log(Order order, decimal amount)
    {
        if (amount <= 0m)
            return;
        if (string.IsNullOrEmpty(order.Reference))
            return;

        if (_refundLog.Count == 0 || amount > 100m)
            _refundLog.Add($"{order.Reference}:{amount}");
        else if (amount > 50m)
            _refundLog.Add($"{order.Reference}:large:{amount}");
        else if (amount > 10m)
            _refundLog.Add($"{order.Reference}:mid:{amount}");
        else
            _refundLog.Add($"{order.Reference}:small:{amount}");

        if (_refundLog.Count > 500 && amount > 1000m)
            _refundLog.Add($"{order.Reference}:flag");
    }
}

internal static class RestockService
{
    public static int Restock(Order order, ReturnState state)
    {
        var moved = 0;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;

            var sku = line.Sku;
            if (string.IsNullOrEmpty(sku))
                continue;
            if (line.Quantity > 100)
                continue;

            if (state.RestockBySku.TryGetValue(sku, out var pending) && pending > 0)
            {
                moved += pending;
                state.RestockBySku[sku] = 0;
            }
            else if (line.Quantity > 50)
            {
                state.RestockBySku[sku] = line.Quantity / 2;
            }
            else if (line.Quantity > 0)
            {
                state.RestockBySku[sku] = line.Quantity;
            }

            if (moved > 100000)
                break;
        }

        return moved;
    }
}
